INSERT INTO feature VALUES('host-effects','effects','Host effects','effect-rows','implemented','notable',NULL,'An interface the host declares at its home, `std.io.Console.Eff` with `print : String ↠ Unit`, `std.io.Stderr.Eff` with `eprint : String ↠ Unit` and `std.io.Stdin.Eff` with `read_line : Unit ↠ String` among them, is performed through its module, `std.io.Console.print(s)`, under a row naming it; the entry''s handler is the host''s, `gandr run` writing each printed line to standard output or standard error and reading standard input, and a `runs` expectation keeping the printed lines, two models of one interface. A source names an interface where it imports its `std` module, `import std.io;`, and the module names its own; anywhere else the interface is an unresolved head whose help names the import. A row naming an interface no host declares is refused by its name.','core-term surface-lowering surface-dispatcher surface-driver','corpus/ledger/features/host-effects.gandr corpus/model/effects/hello.gandr corpus/model/console/answer.gandr corpus/pathological/effects/hello-unprovided.gandr corpus/pathological/effects/host-unimported.gandr crates/surface-driver/tests/cli.rs','corpus/ledger/features/host-effects.gandr',NULL);
